package com.example.lab20; import android.database.Cursor; import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity;
public class MainActivity extends AppCompatActivity { EditText etName,etCourse; TextView tvResult; DatabaseHelper db; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);etName=findViewById(R.id.etName);etCourse=findViewById(R.id.etCourse);Button insert=findViewById(R.id.btnInsert),select=findViewById(R.id.btnSelect);tvResult=findViewById(R.id.tvResult);db=new DatabaseHelper(this);insert.setOnClickListener(v->{String n=etName.getText().toString().trim(),c=etCourse.getText().toString().trim();if(n.isEmpty()||c.isEmpty()){Toast.makeText(this,"Please enter all details",Toast.LENGTH_SHORT).show();return;}if(db.insertStudent(n,c)){Toast.makeText(this,"Data Inserted Successfully",Toast.LENGTH_SHORT).show();etName.setText("");etCourse.setText("");}else Toast.makeText(this,"Insertion Failed",Toast.LENGTH_SHORT).show();});select.setOnClickListener(v->{Cursor cur=db.getAllStudents();StringBuilder out=new StringBuilder();if(cur.getCount()==0)out.append("No Records Found");else while(cur.moveToNext())out.append("ID: ").append(cur.getInt(0)).append("\nName: ").append(cur.getString(1)).append("\nCourse: ").append(cur.getString(2)).append("\n\n");tvResult.setText(out.toString());cur.close();});} }
